pub const KINDS:&[&str]=&["requirements","dx_string_names"];
pub fn name(kind:&str)->&'static str{match kind{"requirements"=>"sys/requirements","dx_string_names"=>"sys/dx_string_names",_=>panic!("unknown fixture kind")}}
pub fn configuration(kind:&str,case:usize)->String{let base="[lint.sys]\nexempt_prefixes=[\"code/modules/unit_tests/\"]\n";match case{0|1=>base.into(),2=>format!("{base}[lint.\"{}\"]\nexempt_prefixes=[\"maps/decl.dm\"]\n",name(kind)),3=>format!("{base}[lint.\"{}\".ceilings]\n{}=100\n",name(kind),if kind=="requirements"{"inline_refusal"}else{"dx_string_names"}),4=>format!("{base}[lint.\"{}\"]\nexempt_prefixes=[\"code/a.dm\",\"maps/decl.dm\"]\n",name(kind)),_=>panic!("unknown case")}}
const REQUIREMENTS:&[(&str,&str)]=&[
("code/a.dm","DECLARE_INTERACTIONS(/obj/control, \\\n\tINTERACT_HAND(\"Use\", PROC_REF(use_widget)) \\\n)\n/datum/interaction/other\n\teffect = /obj/control/proc/else_widget\n/datum/interaction/after_ask\n\teffect = /obj/control/proc/ask_widget\n/datum/interaction/quiet\n\teffect = /obj/control/proc/quiet_widget\n/datum/interaction/condition\n\teffect = /obj/control/proc/condition_widget\n"),
("code/z.dm","/obj/control/proc/use_widget(user)\n\tvar/local = 1\n\tif(!powered)\n\t\tto_chat(user, \"The device has no power\")\n\t\treturn FALSE\n\tif(!anchored) to_chat(user, \"The device is loose\"); return FALSE\n\tif(blocked) return to_chat(user, \"The device is blocked\")\n\tdo_work()\n/obj/control/proc/else_widget(user)\n\tif(blocked)\n\t\tto_chat(user, \"A branch with else is not an inline head refusal\")\n\t\treturn\n\telse\n\t\tdo_work()\n/obj/control/proc/ask_widget(user)\n\tvar/answer = input(user, \"Pick\")\n\tif(!answer)\n\t\tto_chat(user, \"Post-prompt validation is excluded\")\n\t\treturn\n/obj/control/proc/quiet_widget(user)\n\tif(blocked)\n\t\tplaysound(src, \"x\", 1)\n\t\treturn\n/obj/control/proc/condition_widget(user)\n\tif(!use_charge(1))\n\t\tto_chat(user, \"An acting condition is excluded\")\n\t\treturn\n/obj/unrelated/proc/use_widget(user)\n\tif(blocked)\n\t\tto_chat(user, \"Unrelated owner is excluded\")\n\t\treturn\n/proc/ordinary()\n\tREFUSE_IF(blocked)\n\tREFUSE_IF(other) // ALLOW(sys_inline_refusal): this explicit fixture preserves the original annotation usage\n#define REFUSE_IF_MACRO(x) REFUSE_IF(x)\n// REFUSE_IF(comment)\n"),
("maps/decl.dm","/datum/interaction/map\n\teffect = /obj/map_control/proc/map_widget\n/obj/map_control/proc/map_widget(user)\n\tif(blocked)\n\t\tvisible_message(\"The map fixture is blocked\")\n\t\treturn\n"),
("code/.hidden/ignore.dm","\tREFUSE_IF(hidden)\n"),("code/modules/unit_tests/ignore.dm","\tREFUSE_IF(test)\n")];
const STRINGS:&[(&str,&str)]=&[
("code/a.dm","/obj/proc/own_set(var_name)\n\treturn\n"),
("code/z.dm","/proc/string_calls()\n\town_set(src, \"beaker\", I)\n\town_set(src, nameof(beaker), I)\n\ttimed_set(get_holder(x, \"a\"), \"emp\", TRUE)\n\trel_add(src, \"[slot]_link\", T)\n\town_transfer(src, nameof(a), dest, \"b\")\n\town_transfer(src, nameof(a), dest, nameof(b), member = \"x\")\n\tto_chat(user, \"own_set(src, \\\"ignored\\\", I)\")\n\town_set(src, \"allowed\", I) // ALLOW(sys_dx_string_names): this fixture deliberately preserves its literal-name annotation\n\town_widget(src, \"first\", value)\n\town_widget(src, value, \"last\")\n\tom_set(src, \"field\", value)\n\town_widget(src, value, field = \"named argument\")\n\town_widget(src, \"incomplete\"\n// own_set(src, \"comment\", I)\n"),
("maps/decl.dm","/proc/map_calls()\n\trel_add(src, \"map_link\", target)\n"),
("code/.hidden/ignore.dm","\town_set(src, \"hidden\", I)\n"),("code/modules/unit_tests/ignore.dm","\town_set(src, \"test\", I)\n")];
pub fn files(kind:&str,case:usize)->Vec<(&'static str,String)>{let mut out:Vec<_>=match kind{"requirements"=>REQUIREMENTS,"dx_string_names"=>STRINGS,_=>panic!("kind")}.iter().map(|(p,s)|(*p,(*s).to_string())).collect();if kind=="dx_string_names"&&case!=0{out.iter_mut().find(|(p,_)|*p=="code/a.dm").unwrap().1.push_str("/proc/own_widget(datum/holder, var_name, datum/value)\n\treturn\n/proc/om_set(datum/E, name, value)\n\treturn\n");out.iter_mut().find(|(p,_)|*p=="maps/decl.dm").unwrap().1.push_str("/proc/own_widget(datum/holder, datum/value, dest_var)\n\treturn\n");}if kind=="requirements"&&case==1{out.iter_mut().find(|(p,_)|*p=="code/a.dm").unwrap().1.push_str("/datum/interaction/other_owner\n\teffect = /obj/unrelated/proc/use_widget\n");}out}
